sys_script_include.script:
var SAPintegraUtils = Class.create();
SAPintegraUtils.prototype = {
    initialize: function() {},

    getToken: function() {
        try {
            var r = new sn_ws.RESTMessageV2('x_asscs_integra.SAP - ServiceNow', 'Token');
            r.setAuthenticationProfile('basic', gs.getProperty('x_asscs_integra.integraMais_sap_token_profile'));

            var response = r.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();

            var parsedResponse = JSON.parse(responseBody);
            var accessToken = parsedResponse.access_token;

            // gs.info('### SAPintegraUtils Access Token: ' + accessToken);
            // gs.info('### SAPintegraUtils HTTP Status: ' + httpStatus);

            return accessToken;
        } catch (ex) {
            var message = ex.message;
            gs.error('### SAPintegraUtils Error fetching token: ' + message);
            return null;
        }
    },

    postBrand: function(current) {
        try {
            var r = new sn_ws.RESTMessageV2('x_asscs_integra.SAP - ServiceNow', 'criarMarca');
            //r.setEndpoint('https://allos-integration-dev.it-cpi008-rt.cfapps.br10.hana.ondemand.com/http/crm/marca');
            r.setEndpoint(this.getEndpoint() + '/crm/marca');
            r.setRequestHeader('Authorization', 'Bearer ' + this.getToken());
            r.setRequestHeader('Content-Type', 'application/json');

            var requestBody = this.buildBodyBrand(current);
            r.setRequestBody(requestBody);

            gs.info('### Corpo da requisição: ' + requestBody);

            var response = r.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();

            var obj = {
                http: httpStatus,
                responseBody: responseBody,
                requestBody: requestBody,
            };

            gs.info('### SAPintegraUtils.postBrand body enviado e valores: ' + JSON.stringify(obj));

            if (httpStatus == 200 || httpStatus == 201 || httpStatus == 202) {
                //gs.info("### Requisição bem-sucedida: " + JSON.stringify(obj));
                var brandRespose = JSON.parse(responseBody);
                gs.info("### SAPintegraUtils brandcode Criado: " + brandRespose.BrandCode);
                return JSON.stringify(obj);

            } else {
                gs.info("### SAPintegraUtils.postBrand STATUS " + httpStatus);
                gs.info("### SAPintegraUtils.postBrand Response  " + responseBody);
                return "Erro na Integração: " + responseBody;
            }

        } catch (ex) {
            gs.info("Erro na requisição: " + ex.message);
            return "Catch Erro na Integração: " + responseBody + '\n' + ex;
        }
    },

    buildBodyBrand: function(current) {
        var myObj = {
            "BrandName": (current.variables.nome_da_marca && current.variables.nome_da_marca.getDisplayValue()) ||
                (current.variables.nome_marca && current.variables.nome_marca.getDisplayValue()) ||
                "", // Valor padrão caso ambas sejam undefined
            "Nature": (current.variables.natureza_projeto_bahia && current.variables.natureza_projeto_bahia.getDisplayValue()) ||
                (current.variables.new_natureza_projeto_bahia && current.variables.new_natureza_projeto_bahia.getDisplayValue()) ||
                "" // Valor padrão
        };
        return JSON.stringify(myObj);
    },


    attBrand: function(current) {
        try {
            var r = new sn_ws.RESTMessageV2('x_asscs_integra.SAP - ServiceNow', 'atualizarMarca');
            //r.setEndpoint('https://allos-integration-dev.it-cpi008-rt.cfapps.br10.hana.ondemand.com/http/crm/marca');
            r.setEndpoint(this.getEndpoint() + '/crm/marca');
            r.setRequestHeader('Authorization', 'Bearer ' + this.getToken());
            r.setRequestHeader('Content-Type', 'application/json');

            var requestBody = this.buildBodyATTBrand(current);
            r.setRequestBody(requestBody);

            gs.info('### SAPintegraUtils Corpo da requisição - ATT Brand: ' + requestBody);

            var response = r.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();

            var obj = {
                http: httpStatus,
                responseBody: responseBody,
                requestBody: requestBody,
            };

            gs.info('### SAPintegraUtils.attBrand body enviado e valores: ' + JSON.stringify(obj));

            if (httpStatus == 200 || httpStatus == 201 || httpStatus == 202) {
                //gs.info("### Requisição bem-sucedida: " + JSON.stringify(obj));
                var brandRespose = JSON.parse(responseBody);
                gs.info(brandRespose.BrandCode);
                return JSON.stringify(obj);

            } else {
                gs.info("### SAPintegraUtils.attBrand STATUS " + httpStatus);
                gs.info("### SAPintegraUtils.attBrand Response  " + responseBody);
                return "Erro na Integração: " + responseBody;
            }

        } catch (ex) {
            gs.info("Erro na requisição: " + ex.message);
            return "Catch Erro na Integração: " + responseBody + '\n' + ex;
        }
    },

    buildBodyATTBrand: function(current) {

        var grPar = new GlideRecord('x_asscs_allos_o2c_requested_item');
        grPar.addEncodedQuery('sys_id=' + current.request_item);
        grPar.query();

        if (grPar.next()) {
            var brandCode = grPar.variables.brand_code.getValue();
            //var brandCode = 'teste1234';
        }

        var myObj = {
            "BrandCode": brandCode,
            "BrandName": current.variables.nome_da_marca.getDisplayValue(),
            "Nature": current.variables.natureza_projeto_bahia.getDisplayValue()
        };
        return JSON.stringify(myObj);
    },

    getEndpoint: function() {
        var instanceName = gs.getProperty('instance_name');

        if (instanceName == 'allos') {
            gs.info(gs.getProperty('x_asscs_integra.sap_integramais_endpoint_prd'));
            return gs.getProperty('x_asscs_integra.sap_integramais_endpoint_prd');
        } else {
            gs.info(gs.getProperty('x_asscs_integra.sap_integramais_endpoint_dev_qa'));
            return gs.getProperty('x_asscs_integra.sap_integramais_endpoint_dev_qa');
        }
    },

    postLuc: function(current) {
        try {
            var tokenBearer = this.getToken();
            var r = new sn_ws.RESTMessageV2('x_asscs_integra.SAP - ServiceNow', 'criarLuc');
            r.setStringParameterNoEscape('token', tokenBearer);

            //override authentication profile 
            r.setEndpoint(this.getEndpoint() + '/crm/luc');
            r.setRequestHeader('Authorization', 'Bearer ' + tokenBearer);
            r.setRequestHeader('Content-Type', 'application/json');

            var requestBody = this.buildBodyLuc(current);
            r.setRequestBody(requestBody);

            gs.info('### Corpo da requisição: POST LUC ' + requestBody);

            var response = r.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();

            var obj = {
                http: httpStatus,
                responseBody: responseBody,
                requestBody: requestBody,
            };

            gs.info('### SAPintegraUtils.postLuc body enviado e valores: ' + JSON.stringify(obj));

            if (httpStatus == 200 || httpStatus == 201 || httpStatus == 202) {
                gs.info("### Requisição bem-sucedida: " + JSON.stringify(obj));
                return JSON.stringify(obj);

            } else {
                gs.info("### SAPintegraUtils.postLuc STATUS " + httpStatus);
                gs.info("### SAPintegraUtils.postLuc Response  " + responseBody);
                return "Erro na Integração: " + responseBody;
            }

        } catch (ex) {
            gs.info("Erro na requisição: " + ex.message);
            return "Catch Erro na Integração: " + responseBody + '\n' + ex;
        }
    },

    buildBodyLuc: function(current) {
        var myObj = {
            "CompanyCode": "1050", //FORM.company_code
            "BusinessEntity": "PAS", //form.company.name
            "Luc": "vm/test", //form.codigo da nova luc
            "LucType": "RU", // fixo
            "UsageType": "1001", //form.categoria da LUC
            "LucText": "vm/test - teste modifica", //form.codigo da nova luc
            "Building": "1", //form.parte_do_edificio OBS: padronizar Verificar com a Silvana
            "ExistingULNo": "vm/test", //Verificar Só modificar em Alterar, caso seja cadastrar repetir o codigo da nova luc
            "ClassTypeOfUse": "MEGA LOJA", //form.categorizacao_do_espaco
            "ValidFrom": "2022-01-01", //form.data_de_inicio_de_criacao_da_luc
            "ValidTo": "2025-01-01", //Deixar vazio \ quando for inativado tem que ter o campo. - JUNÇÂO e Divisão e qundo é inativação
            "FirstPostingFrom": "2024-10-24", //data_de_inicio_de_criacao_da_luc
            "CPICompanyType": "CPI1",
            "CPIBudgetType": "CG", //verificar com faturamento
            "AdditionalData": {
                "SaleRentable": "LOCA", //verificar com faturamento
                "Piso": "", //verificar com o SAP se é fixo
                "Floor": "401", //form.Pavimento / Andar
                "FloorTo": "401", //form.Pavimento / Andar
                "LocationFloor": "H" //form.corredor_asset
            },
            "Measurements": [{
                    "MeasType": "ZD01", //form. tipo de encargo
                    "MeasValue": 1.0945, //form. tamanho
                    //se for AR Condicionado = zd06 o tamanho vai ser o campo TR
                    //se for Agua = zf02 o tamanho vai ser o campo area metro quadrado
                    //se for IPTU = zd02 o tamanho vai ser o campo fator do rateio
                    //Se for IPTU = zd04 o tamanho vai ser campo area metro quadrado
                    //Se for seguro = zd03 o tamanho vai ser o campo fator do rateio
                    //se for seguro = zd08 o tamanho vai ser campo area metro quadrado
                    // se for energia = zf01 o tamanho vai ser o campo area metro quadrado
                    "MeasValidFrom": "2021-01-01", //ou Inicio da Vigencia (se for filho) ou data de inicio de criação da LUC(se for o proprio chamado)
                    "MeasValidTo": "2023-12-31" //fixar 2040-12-31
                },
                {
                    "MeasType": "ZA03",
                    "MeasValue": 100,
                    "MeasValidFrom": "2024-10-24",
                    "MeasValidTo": "2025-12-31"
                }
            ],
            "Counters": [{
                    "NameCharacteristic": "Z_MEDIDOR_ENERGIA", //puxar codigo baseado no "MeasType":  Verificar se posso enviar dessa forma
                },
                {
                    "NameCharacteristic": "Z_MEDIDOR_AGUA", //puxar codigo baseado no "MeasType": //puxar codigo baseado no "MeasType": 
                }

            ]
        };
        return JSON.stringify(myObj);
    },

    criarCliente: function(current, cpFParameter, cnpjParameter, cRole) {
        try {
            var r = new sn_ws.RESTMessageV2('x_asscs_integra.SAP - ServiceNow', 'criarClientes');
            r.setAuthenticationProfile('oauth2', gs.getProperty('x_asscs_integra.integraMais_sap_bearer_token_profile'));
            r.setEndpoint(this.getEndpoint() + '/crm/business-partner');
            r.setRequestHeader('Content-Type', 'application/json');

            var cpf = cpFParameter; //verificar quando é cpf
            var cnpj = cnpjParameter; //verificar quando é cpf
            var requestBody = '';
            gs.info('Linha 267 ' + cpf);
            gs.info('Linha 268');
            gs.info('Linha 269 ' + cnpj);

            if (cpf) {
                requestBody = this.buildBodyClientesCPF(current, cpf, cRole);
                gs.info('Linha 272');
                gs.info('Linha 273 ' + requestBody);
                r.setRequestBody(requestBody);
            } else if (cnpj) {
                requestBody = this.buildBodyClientesCNPJ(current, cnpj, cRole);
                gs.info('Linha 277');
                gs.info('Linha 278 ' + requestBody);
                r.setRequestBody(requestBody);
            }

            gs.info('### SAPintegraUtils.criarCliente Corpo da requisição: POST Clientes ' + requestBody);

            var response = r.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();

            var obj = {
                http: httpStatus,
                responseBody: responseBody,
                requestBody: requestBody,
            };

            gs.info('### SAPintegraUtils.criarCliente body enviado e valores: ' + JSON.stringify(obj));

            if (httpStatus == 200 || httpStatus == 201 || httpStatus == 202) {
                gs.info("\n\n ### Requisição bem-sucedida criarClientCPF:\n" + JSON.stringify(obj, null, 2));
                return JSON.stringify(obj, null, 2);
            } else {
                gs.info("### SAPintegraUtils.criarClientCPF STATUS " + httpStatus);
                gs.info("### SAPintegraUtils.criarClientCPF Response  " + responseBody);
                return responseBody;
            }

        } catch (ex) {
            gs.info("Erro na requisição criarCliente: " + ex.message);
            return "Catch Erro na Integração: " + responseBody + '\n' + ex;
        }
    },

