        var formattedZipCode = this.formatPostalCode(rawZipCode);

        // var myObj = {
        //     "BasicInfo": {
        //         "CPF": cpfFormatado.toString() || "não há", //form.cpf
        //         "FirstName": current.primeiro_nome.getDisplayValue() || "não há", //form.nome IMPLANTAR
        //         "LastName": current.ultimo_nome.getDisplayValue() || "não há" //form.ultimoNome IMPLANTAR
        //     },
        //     "BPGrouping": "Z001", //fixo para PF  form
        //     "BPType": "Z001", //fixo para PF  form
        //     "SearchTerm1": "IARA+", //ServiceNow form
        //     "SearchTerm2": cpfFormatado.toString() || "não há", //CPF form
        //     "BPAdditionalText": current.number.getValue() || "não há", //Numero do Chamado form
        //     "BPAddress": {
        //         "StreetName": current.variables.address.getDisplayValue() || "não há", //logradouro form
        //         "CityName": current.variables.city.getDisplayValue() || "não há", //cidade form
        //         "HouseNumber": current.variables.custumer_address_number.getDisplayValue() || "não há", //numero form 
        //         "District": current.variables.neighborhood.getDisplayValue() || "não há", //Bairro form
        //         "Complement": current.variables.complement.getDisplayValue() || "não há", //complemento form
        //         "Region": current.variables.uf.getDisplayValue().toUpperCase() || "não há", //UF form
        //         "Country": "BR", //Fixo form
        //         "PostalCode": formattedZipCode || "não há", //cep form 
        //         "PhoneNumber": current.variables.customer_phone_number.getDisplayValue() || "não há", //celular form
        //         "EmailAddress": current.variables.customer_email.getDisplayValue() || "não há", //email do cliente form
        //         "Language": "PT" //Fixo
