        //     }],
        //     "BPRoles": [{
        //             "BPRoleCode": "FLCU00",
        //             "ValidFrom": "1900-01-01",
        //             "ValidTo": "9999-12-31"
        //         },
        //         {
        //             "BPRoleCode": roleCode || "não há",
