                "LastName": current.variables.ultimo_nome.getDisplayValue() || "não há" //form.ultimoNome IMPLANTAR
                // "FirstName": "Patrick" || "não há", // form.nome IMPLANTAR
                // "LastName": "Almeida" || "não há" // form.ultimoNome IMPLANTAR
            },
            "BPGrouping": "Z001", // fixo para PF form
            "BPType": "Z001", // fixo para PF form
            "SearchTerm1": "IARA+", // ServiceNow form
            "SearchTerm2": cpfFormatado.toString() || "não há", // CPF form
