    getConclusion: function(id) {
        var grConclusaoTask = new GlideRecord('x_asscs_allos_o2c_task');
        grConclusaoTask.addEncodedQuery('parent=' + id + '^order=23');
        grConclusaoTask.query();
        if (grConclusaoTask.next()) {
            var dateConclusion = grConclusaoTask.data_de_assinatura_do_contrato_loc.getDisplayValue();
            var formattedDate = new x_asscs_integra.SAPintegraUtils().formatDateToISO(dateConclusion);
            gs.info('Data formatada: ' + formattedDate);
            return formattedDate;
        }
    },

    getTermSales: function(id, inicio_da_vigencia) {

        var grXAAO2RI = new GlideRecord('x_asscs_allos_o2c_requested_item');
        grXAAO2RI.addEncodedQuery("sys_id=" + id);
        grXAAO2RI.query();

        var termSaleRulesRhythm = [];


        if (grXAAO2RI.next()) {

            var rowData = JSON.parse(grXAAO2RI.variables.aluguel_percentual_vendas);
            var termNumber = 10;
            for (var i = 0; i < rowData.length; i++) {

                var row = rowData[i];
                var obj = {
                    "TermNumber": termNumber.toString(), // de  10 em 10
                    "ValidFrom": inicio_da_vigencia, // Substitua pelo valor correto, caso disponível
                    "FrequencyType": "11", // verificar com jessica
                    "FrequencyStartDate": row.fim_periodo_vs, //Usando o valor de `fim_periodo_vs`
                    "Frequency": "001", //padrao
                    "FrequencyUnit": "0", //padrao
                    "ProRataMethod": "0", // verificar
                    "ProRataMethodCalculation": "0", //verificar
                    "PayCredits": false // verificar
                    //	"FixedPeriod: "// verificar

                };
            }
            termSaleRulesRhythm.push(obj);
            termNumber += 10;
            return termSaleRulesRhythm;
        } else {
            gs.info("Nenhum registro encontrado para o sys_id especificado.");
        }

    },


    getContractStartDate: function(id) {
        var grConclusaoTask = new GlideRecord('x_asscs_allos_o2c_task');
        grConclusaoTask.addEncodedQuery('parent=' + id + '^order=14');
        grConclusaoTask.query();
        if (grConclusaoTask.next()) {

            var dateStartInicioVigencia = grConclusaoTask.variables.inicio_da_vigencia.getDisplayValue();
            var formattedDate = new x_asscs_integra.SAPintegraUtils().formatDateToISO(dateStartInicioVigencia);
            var dateStartMudanca = grConclusaoTask.data_inicio_vigencia_atualizada_nova_loc.getDisplayValue();
            var dateEndMudanca = grConclusaoTask.data_fim_vigencia_atualizada_nova_loc.getDisplayValue();
            var formattedDateMudanca = new x_asscs_integra.SAPintegraUtils().formatDateToISO(dateStartMudanca);
            var vigencia = grConclusaoTask.possui_mudanca_de_vigencia_nova_loc;
            var tipoGarantiaTask = grConclusaoTask.tipo_de_garantia_fiador_nova_loc;
            var dataInauguracaoTask = grConclusaoTask.data_da_previsao_de_inauguracao;
            var cliente_possui_cadastro_sap_locatarioTask = grConclusaoTask.cadastro_locatario_sap;
            var codigo_bp_sap_locatarioTask = grConclusaoTask.codigo_bp_locatario;
            var codEmpresa = grConclusaoTask.codigo_da_empresa_nov_loc.getValue();
            var possuiFiador = grConclusaoTask.possui_fiador.getValue();

            if (!dateEndMudanca) {
                dateEndMudanca = '2024-12-31';
            } else {
                dateEndMudanca = new x_asscs_integra.SAPintegraUtils().formatDateToISO(dateEndMudanca);
            }


            return {
                formattedDate: formattedDate,
                formattedDateMudanca: formattedDateMudanca,
                dateEndMudanca: dateEndMudanca,
                vigencia: vigencia,
                tipoGarantiaTask: tipoGarantiaTask,
                dataInauguracaoTask: dataInauguracaoTask,
                cliente_possui_cadastro_sap_locatarioTask: cliente_possui_cadastro_sap_locatarioTask,
                codigo_bp_sap_locatarioTask: codigo_bp_sap_locatarioTask,
                codEmpresa: codEmpresa,
                possuiFiador: possuiFiador
            };
        } else {
            return 'Error na função getContractStartDate';
        }

    },

    getRoleCode: function(funcaoCliente) {
        // FLCU00 - Cliente (contab.financ.)
        // TR0600 - Locatário
        // TR0200 - Fiador
        // TR0806 - Representante Legal"
        if (funcaoCliente == 'Tenant') {
            return "TR0600";
        } else if (funcaoCliente == 'Legal representative') {
            return "TR0806";
        } else if (funcaoCliente == 'Financial representative') {
            return "FLCU00";
        } else if (funcaoCliente == 'Guarantor') {
            return "TR0200";
        }
    },


    formatDateToISO: function(dateString) {
        var dateParts = dateString.split('/');
        var day = dateParts[0];
        var month = dateParts[1];
        var year = dateParts[2];
        var dataNova = year + '-' + month + '-' + day;

        return dataNova;
    },


    payloadContratoFaturamento: function(idTask) {

        var currentID = idTask; //current.sys_id
        var currentRecord = new GlideRecord("x_asscs_allos_o2c_task");
        if (currentRecord.get(currentID)) {

            var myObj = {
                code: "",
                payload: "",
                message: ""
            };

            var number = currentRecord.parent.getDisplayValue();
            var tipoProposta = currentRecord.variables.proposal_type.getValue();
            var periodoVigenciaInderterminado = currentRecord.variables.periodo_de_vigencia_indeterminado.getValue();
            var inicioVigencia = currentRecord.variables.inicio_da_vigencia.getValue();
            var registered_brand = currentRecord.variables.registered_brand.getValue();
            var tipo_Operador = currentRecord.variables.tipo_operador.getValue();
            var indiceCorrecao = currentRecord.variables.indice_de_correcao.getDisplayValue();
            var fimdaVigencia = '';
            var possuiFPP = currentRecord.variables.possui_cobranca_de_fpp.getValue();
            if (periodoVigenciaInderterminado == 'No') {
                periodoVigenciaInderterminado = false;
                fimdaVigencia = currentRecord.variables.fim_da_vigencia.getValue();
            }

            var mesBaseReajuste = currentRecord.variables.mes_base_de_reajuste.getDisplayValue();

            var partesData = mesBaseReajuste.split('/');
            var mes = partesData[0];
            var ano = parseInt(partesData[1]);
            var dia = "01";
            ano += 1;
            var novaDataReajuste = ano + "-" + mes + "-" + dia;

            var possuiCondicaoEspecialAluguel = currentRecord.variables.condicoes_especial_para_a.getValue();
            var unitCode = currentRecord.variables.shopping.u_unit_code.getDisplayValue();
            gs.info("unitCode " + unitCode);
            if (!unitCode) {
                myObj = {
                    code: "400",
                    payload: "",
                    message: "ERRO: código da unidade vazio"
                };
                return JSON.stringify(myObj);
            }
        }

