    getContractType: function(proposalType, naturezaDaProposta) {

        switch (true) {
            case proposalType === "store":
                return "Z001";
            case proposalType === "mall" && naturezaDaProposta != "temporary":
                return "Z002";
            case proposalType === "Mall" && naturezaDaProposta == "temporary":
                return "Z006";
            default:
                return "Tipo desconhecido";
        }
    },

    formatPostalCode: function(rawZipCode) {
        var zipCode = rawZipCode.replace(/[^\d]/g, '');
        if (zipCode.length === 8) {
            // Insere o hífen para o formato 28015-223
            return zipCode.replace(/(\d{5})(\d{3})/, "$1-$2");
        } else {
            gs.error('Código Postal inválido. Deve conter 8 dígitos.');
            return null;
        }
    },

