    formatDateToDDMMYYYY: function(dateString) {
        var date = new Date(dateString);
        var day = ("0" + date.getDate()).slice(-2);
        var month = ("0" + (date.getMonth() + 1)).slice(-2);
        var year = date.getFullYear();
        return year + '-' + month + '-' + day;
    },

    descontoUIAction: function(current) {
        if ((current.request_item.cat_item == '922255dc1ba0029068724112fa4bcb43' && current.assigned_to != '' && current.order == '22' && current.u_flag_contrato == false) && (current.variables.tipo_de_desconto == 'padrao' || current.variables.tipo_de_desconto == 'carencia' || current.variables.tipo_de_desconto == 'extensao')) {
            return true;
        } else {
            return false;
        }
    },


